//! Author properties on genuine inert XML Elements use the shared native store.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=mount></div><input id=field value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://element-author.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn inert_element_properties_exact_keys_descriptors_symbols_and_native_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var xml=document.implementation.createDocument('urn:original','p:Root'),source=xml.documentElement,state={held:source},raw='A\ud800z',literal='A�z',symbol=Symbol('binding'),hits=0;source[raw]=state;source[literal]=17;source[symbol]=23;Object.defineProperty(source,'binding',{get:function(){hits++;if(this!==source)throw 'getter receiver';return state;},enumerable:true,configurable:true});if(source[raw]!==state||source[literal]!==17||source[symbol]!==23||source.binding!==state||hits!==1||Object.getOwnPropertyDescriptor(source,raw).value!==state||Object.getOwnPropertySymbols(source)[0]!==symbol||Object.keys(source).indexOf(raw)<0||Object.keys(source).indexOf(literal)<0||Object.getPrototypeOf(source)!==Element.prototype||!(source instanceof Element))throw 'actual ordinary XML store';source.className='native';var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'className'),a=source.getAttributeNode('class');Object.defineProperty(source,'className',{get:function(){hits++;return 'author';},configurable:true});if(source.className!=='author'||descriptor.get.call(source)!=='native'||a.value!=='native')throw 'native getter ignores own shadow';descriptor.set.call(source,'B\udfffz');if(a.value!=='B\udfffz'||source.className!=='author')throw 'native setter ignores own shadow';delete source.className;if(source.className!=='B\udfffz'||Object.hasOwn(source,'className'))throw 'native fallback';delete source[raw];if(source[raw]!==undefined||source[literal]!==17||source[symbol]!==23)throw 'exact deletion';
"#);}
#[test]
fn inert_element_properties_author_class_list_getter_preserves_original_forwarded_value(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var xml=document.implementation.createDocument(null,'Root'),source=xml.documentElement,descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'classList'),order='',seen,target={set value(v){order+='set';seen=v;}},value={toString:function(){order+='bad';return 'bad';}};Object.defineProperty(source,'classList',{get:function(){order+='get';return target;},configurable:true});descriptor.set.call(source,value);if(order!=='getset'||seen!==value||source.getAttribute('class')!==null||Object.getOwnPropertyDescriptor(source,'classList').get===undefined)throw 'real XML forwarding';var marker={};Object.defineProperty(source,'classList',{get:function(){throw marker;},configurable:true});try{descriptor.set.call(source,value);throw 'getter missing';}catch(e){if(e!==marker)throw e;}if(order!=='getset'||source.attributes.length)throw 'abrupt forwarding';delete source.classList;source.authorRecovery='fresh';if(source.authorRecovery!=='fresh'||Object.hasOwn(source,'classList'))throw 'fresh ordinary recovery';
"#);}
#[test]
fn inert_element_properties_clone_import_and_adoption_preserve_actual_native_state(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var xml=document.implementation.createDocument('urn:original','p:Root'),source=xml.documentElement,target=document.implementation.createDocument('urn:other','q:Root'),state={held:source},hits=0,symbol=Symbol('binding');source.className='A\ud800z';source.authorState=state;source[symbol]=17;Object.defineProperty(source,'className',{get:function(){hits++;throw 'author class getter';},configurable:true});Object.defineProperty(source,'binding',{get:function(){hits++;throw 'author binding getter';},configurable:true});var a=source.getAttributeNode('class'),copy=source.cloneNode(true),imported=target.importNode(source,true);if(hits||copy===source||copy.ownerDocument!==xml||imported.ownerDocument!==target||copy.getAttribute('class')!=='A\ud800z'||imported.className!=='A\ud800z'||copy.authorState!==undefined||imported.authorState!==undefined||copy[symbol]!==undefined||Object.hasOwn(copy,'binding')||Object.hasOwn(copy,'className'))throw 'native clone ignores author getters';if(target.adoptNode(source)!==source||source.ownerDocument!==target||source.authorState!==state||source[symbol]!==17||source.getAttributeNode('class')!==a||a.ownerDocument!==target||hits)throw 'actual adoption identity';delete source.className;source.className='fresh';if(a.value!=='fresh'||copy.className!=='A\ud800z'||imported.className!=='A\ud800z')throw 'independent native state';
"#);}

#[test]
fn inert_element_properties_quota_refusal_preserves_native_and_exact_author_state(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var xml=document.implementation.createDocument(null,'Root'),source=xml.documentElement,state={held:source},raw='A\ud800z',newKey='B\udfffz',symbol=Symbol('binding');source.className='native';source[raw]=state;source[symbol]=17;"#);let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits);for expression in ["source.unpublishedBinding=17;","source[newKey]=23;"]{let allowance=p.runtime.event_property_allowance_for_test(0);assert_eq!(p.console_eval(&mut d,&mut f,expression).errors,1);p.runtime.event_property_allowance_for_test(allowance);assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits),before);run(&mut d,&mut f,&mut p,"if(Object.hasOwn(source,'unpublishedBinding')||Object.hasOwn(source,newKey)||source[raw]!==state||source[symbol]!==17||source.className!=='native')throw 'atomic author refusal';");}run(&mut d,&mut f,&mut p,"source[newKey]='recovered';if(source[newKey]!=='recovered'||source[raw]!==state)throw 'fresh recovery';");}
#[test]
fn inert_element_properties_saved_child_origin_precedes_author_getter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var xml=document.implementation.createDocument(null,'Root'),source=xml.documentElement,hits=0,state={held:source};Object.defineProperty(source,'binding',{get:function(){hits++;return state;},configurable:true});var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var read=frame.contentWindow.Function('node','return node.binding;');if(read(source)!==state||hits!==1)throw 'same-origin native author store';"#);p.set_location(&crate::navigation::address("https://other-element-author.test/",&crate::navigation::Location::home()).unwrap());let before=(d.nodes.len(),p.state.attributes.len(),p.state.dom_commits);assert_eq!(p.console_eval(&mut d,&mut f,"read(source);").errors,1);assert!(p.report().contains("same-origin")||p.report().contains("Security"),"{}",p.report());assert_eq!((d.nodes.len(),p.state.attributes.len(),p.state.dom_commits),before);run(&mut d,&mut f,&mut p,"if(hits!==1)throw 'origin before getter';source.recovered=17;if(source.recovered!==17)throw 'local fresh recovery';");}
#[test]
fn inert_element_properties_no_slot_namespace_variants_have_independent_native_stores(){let(mut d,mut f,mut p)=fixture();let limit=p.state.node_limit;let count=d.nodes.len();p.state.node_limit=count;run(&mut d,&mut f,&mut p,r#"var owner=new Document(),nodes=[owner.createElementNS(null,'Root'),owner.createElementNS('urn:other','p:Root'),owner.createElementNS('http://www.w3.org/1998/Math/MathML','math')],key='A\ud800z',symbol=Symbol('binding');for(var i=0;i<nodes.length;i++){var n=nodes[i];n[key]=i;n[symbol]=n;Object.defineProperty(n,'binding',{value:n,writable:true,enumerable:true,configurable:true});n.className='native'+i;if(n[key]!==i||n[symbol]!==n||n.binding!==n||n.ownerDocument!==owner||!(n instanceof Element)||n.getAttribute('class')!=='native'+i||Object.keys(n).indexOf(key)<0)throw 'no-slot genuine store';}delete nodes[0][key];if(nodes[0][key]!==undefined||nodes[1][key]!==1||nodes[2][key]!==2)throw 'separate owner identity';"#);assert_eq!(d.nodes.len(),count);p.state.node_limit=limit;}
